def base(name):return subprocess.check_output(['git','show',f'{BASE}:4. Latex/paper_A/{name}'],cwd=R).decode('utf8')
def uncolor(s):
    # Remove only provenance wrappers, preserving their contents and all other braces.
    while re.search(r'\\(?:old|rev|new)\{',s):
        m=re.search(r'\\(?:old|rev|new)\{',s);start=m.end();k=start;depth=1
        while depth:
            if s[k]=='{' and s[k-1]!='\\':depth+=1
            if s[k]=='}' and s[k-1]!='\\':depth-=1
            k+=1
        s=s[:m.start()]+s[start:k-1]+s[k:]
    s=re.sub(r'\\(?:begin|end)\{(?:revision|addition)\}\n?','',s)
    s=s.replace('{revised}','{reused}').replace('{added}','{reused}')
    return s
